(2597172, 358000, 24454, '<td valign="top">This is beautiful!   One of the better ones because its so crystal clear!  No smoke.  No blur!  Excellent work!  9</td>', 'This is beautiful!   One of the better ones because its so crystal clear!  No smoke.  No blur!  Excellent work!  9', '2006-07-07 12:15:08.000000', NULL, 1),
(2597177, 358801, 24454, '<td valign="top">This is awesome!!!!   Not only fireworks, but a story!  Executed so well!  I hope this one ribbons.  It certainly stands out!  10</td>', 'This is awesome!!!!   Not only fireworks, but a story!  Executed so well!  I hope this one ribbons.  It certainly stands out!  10', '2006-07-07 12:16:14.000000', NULL, 1),
(2597189, 358681, 24454, '<td valign="top">Wow!   I didn''t know El Paso could look so beautiful (sorry.  I used to live there and hated it). . .this is awesome!!!   Your fireworks are crystal clear, and the added beauty of the lights of the city!  Wonderful!!!  9</td>', 'Wow!   I didn''t know El Paso could look so beautiful (sorry.  I used to live there and hated it). . .this is awesome!!!   Your fireworks are crystal clear, and the added beauty of the lights of the city!  Wonderful!!!  9', '2006-07-07 12:19:11.000000', NULL, 1),
