(2608963, 358702, 45082, '<td valign="top">This one is going to be hard to beat!  I predict a ribbon for this one.  Great job!</td>', 'This one is going to be hard to beat!  I predict a ribbon for this one.  Great job!', '2006-07-10 22:47:39.000000', NULL, 1),
(2609093, 357974, 42495, '<td valign="top">You really captured the look of a tired child; great composition.  For me, the border takes away from the picture a bit.</td>', 'You really captured the look of a tired child; great composition.  For me, the border takes away from the picture a bit.', '2006-07-10 23:24:55.000000', NULL, 1),
(2609096, 358676, 42495, '<td valign="top">Good composition and color.</td>', 'Good composition and color.', '2006-07-10 23:25:18.000000', NULL, 1),
(2609106, 358718, 42495, '<td valign="top">Good composition and colors.  A single burst may have placed more emphasis on the statue.</td>', 'Good composition and colors.  A single burst may have placed more emphasis on the statue.', '2006-07-10 23:26:29.000000', NULL, 1),
(2609119, 359126, 42495, '<td valign="top">Great job on the composition and red smoke.  Trees add to the effect.</td>', 'Great job on the composition and red smoke.  Trees add to the effect.', '2006-07-10 23:27:40.000000', NULL, 1),
(2609753, 359221, 61913, '<td valign="top">This picture totally engulfs the idea of our nation''s birthday!</td>', 'This picture totally engulfs the idea of our nation''s birthday!', '2006-07-11 02:29:58.000000', NULL, 1),
(2609776, 359162, 49255, '<td valign="top">Love the energy of the colours.</td>', 'Love the energy of the colours.', '2006-07-11 02:37:14.000000', NULL, 1),
(2610081, 358676, 61424, '<td valign="top">Great capture!</td>', 'Great capture!', '2006-07-11 05:14:51.000000', NULL, 1),
(2610271, 358702, 42495, '<td valign="top">Nice view overlooking the river; good timing to catch a single burst.  A crop on the right to get rid of some of the dark area may make this even better.</td>', 'Nice view overlooking the river; good timing to catch a single burst.  A crop on the right to get rid of some of the dark area may make this even better.', '2006-07-11 08:18:59.000000', NULL, 1),
(2610283, 359048, 42495, '<td valign="top">Nice angle from within the crowd.  It looks a little soft to me.</td>', 'Nice angle from within the crowd.  It looks a little soft to me.', '2006-07-11 08:22:28.000000', NULL, 1),
(2610288, 358713, 42495, '<td valign="top">Nice capture of what was visible from your viewpoint; your title sums it up well.</td>', 'Nice capture of what was visible from your viewpoint; your title sums it up well.', '2006-07-11 08:23:45.000000', NULL, 1),
(2610292, 358924, 42495, '<td valign="top">Well timed and clever title.</td>', 'Well timed and clever title.', '2006-07-11 08:24:55.000000', NULL, 1),
(2610294, 358725, 42495, '<td valign="top">Really good composition and timing to catch it perfectly.</td>', 'Really good composition and timing to catch it perfectly.', '2006-07-11 08:25:59.000000', NULL, 1),
(2610301, 358769, 42495, '<td valign="top">You''re not kidding about the mess!  The composition is what really makes this picture work well, with the fireworks, mess, and observers.  A shorter exposure may have avoided the blown out firworks.</td>', 'You''re not kidding about the mess!  The composition is what really makes this picture work well, with the fireworks, mess, and observers.  A shorter exposure may have avoided the blown out firworks.', '2006-07-11 08:28:48.000000', NULL, 1),
(2610310, 358723, 42495, '<td valign="top">This is a 3D look to it. Good job cropping to get it just right.</td>', 'This is a 3D look to it. Good job cropping to get it just right.', '2006-07-11 08:30:19.000000', NULL, 1),
(2610312, 359340, 42495, '<td valign="top">The people in the boat add to your composition.</td>', 'The people in the boat add to your composition.', '2006-07-11 08:31:05.000000', NULL, 1),
(2610316, 359068, 42495, '<td valign="top">Different take on the "fireworks" theme and it works for me.  It looks like there is a loss of resolution somewhere; perhaps you had to crop a lot to get the lightning to fill the frame.</td>', 'Different take on the "fireworks" theme and it works for me.  It looks like there is a loss of resolution somewhere; perhaps you had to crop a lot to get the lightning to fill the frame.', '2006-07-11 08:32:42.000000', NULL, 1),
(2610319, 359316, 42495, '<td valign="top">Your composition here is excellent and it tells a story.  However, the grain (which may be intentional), distracts a lot.  It keeps it from being a standout in the challenge.</td>', 'Your composition here is excellent and it tells a story.  However, the grain (which may be intentional), distracts a lot.  It keeps it from being a standout in the challenge.', '2006-07-11 08:34:04.000000', NULL, 1),
(2610333, 358778, 42495, '<td valign="top">Really good composition and I like the simplicity of it.  The border does a great job of ending the burst.  This would look cool hanging on a wall.  The noise in the background takes away a little bit from an excellent photo.</td>', 'Really good composition and I like the simplicity of it.  The border does a great job of ending the burst.  This would look cool hanging on a wall.  The noise in the background takes away a little bit from an excellent photo.', '2006-07-11 08:41:04.000000', NULL, 1),
