(2617126, 358051, 35274, '<td valign="top">the shapes of the sparks and that good sharpness make this quite interesting.</td>', 'the shapes of the sparks and that good sharpness make this quite interesting.', '2006-07-13 00:43:26.000000', NULL, 1),
(2617132, 358998, 35274, '<td valign="top">Love it! I don''t think I''ve seen any entries that have a stadium as a setting, at least not like this. very well done.</td>', 'Love it! I don''t think I''ve seen any entries that have a stadium as a setting, at least not like this. very well done.', '2006-07-13 00:44:34.000000', NULL, 1),
(2617135, 358773, 35274, '<td valign="top">gotta love those whispy light trails! the slight tinge of red to the side is a bit distracting though.</td>', 'gotta love those whispy light trails! the slight tinge of red to the side is a bit distracting though.', '2006-07-13 00:45:10.000000', NULL, 1),
(2617136, 359310, 35274, '<td valign="top">Wonderful and creative idea if you don''t have access to the real thing. I really hope this does well!</td>', 'Wonderful and creative idea if you don''t have access to the real thing. I really hope this does well!', '2006-07-13 00:46:04.000000', NULL, 1),
(2617140, 358771, 35274, '<td valign="top">I can see where you were going with this, but i think the saturation is just a little too much.</td>', 'I can see where you were going with this, but i think the saturation is just a little too much.', '2006-07-13 00:47:13.000000', NULL, 1),
(2617144, 359282, 35274, '<td valign="top">How amazing! I really love the thin, stringy light trails and how the explosions just seem to fill the entire frame.</td>', 'How amazing! I really love the thin, stringy light trails and how the explosions just seem to fill the entire frame.', '2006-07-13 00:48:29.000000', NULL, 1),
